/* 知夏 · 变量结构
 *
 * 这份 Schema 描述养成玩法的全部数据。三处消费方共用它，不允许各存一套：
 * 1. 酒馆助手脚本（打工结算、状态栏渲染、场景判定）
 * 2. 楼层里的养成面板界面
 * 3. 本地检查脚本
 *
 * 前缀约定（MVU 规定）：
 * - 无前缀：AI 可见可更新
 * - `_` 前缀：AI 可见不可更新，只由脚本写
 * - `$` 前缀：AI 看不见，只由脚本写
 *
 * 数值一律写成 `z.coerce.number().prefault(开局值).transform(钳制)`。
 * 顺序不能反：prefault 是给输入补默认值的，挂在 transform 后面就永远不会生效。
 * 钳制用 transform 不用 min/max，保证 Schema.parse(Schema.parse(x)) 与单次解析一致。
 *
 * 不 import zod 与 lodash：酒馆运行环境自带 `z` 与 `_`。
 */
/** 四个打工场地。场地里的活就是对应的小游戏，结算参数只在这里改一处。 */
export const 场地表 = {
    工地: {
        时段: ['上午', '下午'],
        活: {
            搬料配重: { 时薪: 90, 体力: 22, 时长: 3 },
        },
    },
    后厨: {
        时段: ['上午', '下午', '傍晚'],
        活: {
            出餐顺序: { 时薪: 110, 体力: 15, 时长: 3 },
        },
    },
    仓库: {
        时段: ['下午', '夜里'],
        活: {
            分拣: { 时薪: 100, 体力: 18, 时长: 3 },
        },
    },
    夜市: {
        时段: ['夜里', '深夜'],
        活: {
            送货路线: { 时薪: 140, 体力: 25, 时长: 4 },
        },
    },
};
/** 熟练度的四档与倍率。门槛改一处，界面的档位文字跟着走。 */
export const 熟练档 = [
    { 名: '生手', 门槛: 20, 倍率: 1.0 },
    { 名: '上手', 门槛: 45, 倍率: 1.15 },
    { 名: '熟手', 门槛: 75, 倍率: 1.3 },
    { 名: '老手', 门槛: 100, 倍率: 1.5 },
];
export function 取熟练档(值) {
    const 数 = Number(值);
    const 钳 = Number.isFinite(数) ? _.clamp(数, 0, 100) : 0;
    return 熟练档.find(档 => 钳 < 档.门槛) ?? 熟练档[熟练档.length - 1];
}
/** 体力低于这条线，打工收入打折，正文里也该写成「今天实在没力气了」。 */
export const 疲劳阈值 = 30;
/** 四个季节。服装按季进货，穿错季会有后果，所以季节是一个真变量，不是装饰。 */
export const 季节表 = ['春', '夏', '秋', '冬'];
/** 妹妹年龄落在第几个阶段（1 到 4）。阶段决定面板显示哪一档内容。 */
export function 取阶段(年龄) {
    if (年龄 < 7)
        return 1;
    if (年龄 < 9)
        return 2;
    if (年龄 < 12)
        return 3;
    return 4;
}
export const 起始年 = 1;
const 结构 = z.object({
    时间: z
        .object({
        年: z.coerce.number().prefault(起始年),
        月: z.coerce
            .number()
            .prefault(9)
            .transform(v => _.clamp(v, 1, 12)),
        日: z.coerce
            .number()
            .prefault(1)
            .transform(v => _.clamp(v, 1, 28)),
        时段: z.string().prefault('傍晚'),
        季节: z.string().prefault('秋'),
        总天数: z.coerce.number().prefault(0),
    })
        .prefault({}),
    钱: z.coerce.number().prefault(320),
    哥哥: z
        .object({
        体力: z.coerce
            .number()
            .prefault(80)
            .transform(v => _.clamp(v, 0, 100)),
        今日已打工: z.coerce
            .number()
            .prefault(0)
            .transform(v => _.clamp(v, 0, 1)),
    })
        .prefault({}),
    妹妹: z
        .object({
        年龄: z.coerce
            .number()
            .prefault(5)
            .transform(v => _.clamp(v, 5, 16)),
        阶段: z.coerce
            .number()
            .prefault(1)
            .transform(v => _.clamp(v, 1, 4)),
        饥饿: z.coerce
            .number()
            .prefault(70)
            .transform(v => _.clamp(v, 0, 100)),
        心情: z.coerce
            .number()
            .prefault(60)
            .transform(v => _.clamp(v, 0, 100)),
        健康: z.coerce
            .number()
            .prefault(90)
            .transform(v => _.clamp(v, 0, 100)),
        依赖: z.coerce
            .number()
            .prefault(40)
            .transform(v => _.clamp(v, 0, 100)),
        病症: z.string().prefault('无'),
    })
        .prefault({}),
    /** 场景联动：正文里哥哥当前在哪。`可打工` 决定打工页签能不能开。 */
    场景: z
        .object({
        地点: z.string().prefault('家'),
        可打工: z.coerce
            .number()
            .prefault(0)
            .transform(v => _.clamp(v, 0, 1)),
    })
        .prefault({}),
    物品: z
        .record(z.string().describe('物品名'), z.object({
        数量: z.coerce.number().prefault(0),
        类别: z.string().prefault('其他'),
    }))
        .prefault({})
        .transform(表 => _.pickBy(表, 条目 => Number(条目?.数量) > 0)),
    衣柜: z
        .object({
        已购: z.record(z.string().describe('衣服名'), z.coerce.number()).prefault({ 旧T恤: 1, 旧裤子: 1 }),
        当前穿: z.string().prefault('旧T恤'),
    })
        .prefault({}),
    /** 熟练度与解锁进度：AI 看不到，与正文无关，只由面板写。 */
    $进度: z
        .object({
        熟练: z
            .record(z.string().describe('场地名'), z.coerce.number().transform(v => _.clamp(v, 0, 100)))
            .prefault({ 工地: 0, 后厨: 0, 仓库: 0, 夜市: 0 }),
        次数: z
            .record(z.string().describe('场地名'), z.coerce.number().prefault(0))
            .prefault({ 工地: 0, 后厨: 0, 仓库: 0, 夜市: 0 }),
        上次结算: z.string().prefault(''),
    })
        .prefault({}),
    /** 面板自身的开关：AI 看不到。 */
    $界面: z
        .object({
        已打开: z.coerce
            .number()
            .prefault(0)
            .transform(v => _.clamp(v, 0, 1)),
    })
        .prefault({}),
});
export const Schema = 结构;
